SELECT
a.*,
(
SELECT
t.guoku_dscr
FROM
dmcode.cm_guoku_dimnsn t
WHERE
a.INSPECTED_GUOKU_ID = t.guoku_id
) AS INSPECTED_GUOKU_DSCR,
(
SELECT
c.ENUM_DSCR
FROM
`enumset`.`cm_guoku_enumeration` c
WHERE
c.ENUM_TYPE_ID = '12'
AND c.ENUM_ID = a.INSPECTION_TASK_TYPE
) AS INSPECTION_TASK_TYPE_DSCR,
(
SELECT
c.ENUM_DSCR
FROM
`enumset`.`cm_guoku_enumeration` c
WHERE
c.ENUM_TYPE_ID = '13'
AND c.ENUM_ID = a.INSPECTION_TASK_STATE
) AS IINSPECTION_TASK_STATE_DSCR,
a.IS_LOCK_GROUP AS IS_LOCK,
a.INSPECTION_TASK_BEGINTIME  AS TASK_TIME
FROM
inspection.`inspection_task_postsv` a
WHERE
1 = 1

    AND a.INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}


    AND a.INSPECTION_TASK_YEAR = #{params.INSPECTION_TASK_YEAR}


    AND a.INSPECTION_TASK_TYPE = #{params.INSPECTION_TASK_TYPE}


    AND a.INSPECTION_TASK_NAME like '%${params.INSPECTION_TASK_NAME}%'


    AND a.INSPECTION_GUOKU = #{params.INSPECTION_GUOKU}



        AND a.INSPECTED_GUOKU_ID = #{params.INSPECTED_GUOKU_ID}




        AND a.INSPECTED_GUOKU_ID = #{params.guoku_id}



    AND a.INSPECTION_TASK_STATE = #{params.INSPECTION_TASK_STATE}


    AND a.INSPECTION_TASK_BEGINTIME >= #{params.INSPECTION_TASK_BEGINTIME}


    AND a.INSPECTION_TASK_BEGINTIME <= #{params.INSPECTION_TASK_ENDTIME}


    AND a.INSPECTION_PLAN_ID = #{params.INSPECTION_PLAN_ID}


    AND a.IS_LOCK_MAIN = #{params.IS_LOCK_MAIN}


    AND a.IS_LOCK_GROUP = #{params.IS_LOCK_GROUP}


    AND a.BOOKORG_ID = #{params.BOOKORG_ID}


    AND a.BOOKORG_DSCR like '%${params.BOOKORG_DSCR}%'


    AND a.CHECK_ORG = #{params.CHECK_ORG}


    AND a.CHECK_ORG_DSCR like '%${params.CHECK_ORG_DSCR}%'


    AND a.CHECKED_ORG = #{params.CHECKED_ORG}


    AND a.CHECKED_ORG_DSCR like '%${params.CHECKED_ORG_DSCR}%'

order by CAST(a.CREATE_TIME AS DATE) DESC
LIMIT ${params.page},${params.rows}

