    IS_LOCK_MAIN = #{params.IS_LOCK_MAIN},


    IS_LOCK_GROUP = #{params.IS_LOCK_GROUP},


    UPDATE_TIME = #{params.UPDATE_TIME},

INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}
WHERE INSPECTION_TASK_ID = #{params.INSPECTION_TASK_ID}

